using namespace std;

class Solution {
public:
    long long maxProfit(vector<int>& workers, vector<vector<int>>& tasks) {
        unordered_map<int, priority_queue<int>> d;
        for (const auto& t : tasks) {
            d[t[0]].push(t[1]);
        }

        long long ans = 0;
        for (int w : workers) {
            if (d.count(w) && !d[w].empty()) {
                ans += d[w].top();
                d[w].pop();
            }
        }

        int maxRem = 0;
        for (auto& [skill, pq] : d) {
            if (!pq.empty()) {
                maxRem = max(maxRem, pq.top());
            }
        }
        return ans + maxRem;
    }
};

import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;

class Solution {
    public long maxProfit(int[] workers, int[][] tasks) {
        Map<Integer, PriorityQueue<Integer>> d = new HashMap<>();
        for (int[] t : tasks) {
            int skill = t[0], profit = t[1];
            d.computeIfAbsent(skill, k -> new PriorityQueue<>((a, b) -> b - a)).offer(profit);
        }

        long ans = 0;
        for (int w : workers) {
            if (d.containsKey(w) && !d.get(w).isEmpty()) {
                ans += d.get(w).poll();
            }
        }

        int maxRem = 0;
        for (PriorityQueue<Integer> pq : d.values()) {
            if (!pq.isEmpty()) {
                maxRem = Math.max(maxRem, pq.peek());
            }
        }
        return ans + maxRem;
    }
}

/**
 * @param {number[]} workers
 * @param {number[][]} tasks
 * @return {number}
 */
var maxProfit = function(workers, tasks) {
    const d = new Map();
    for (const [skill, profit] of tasks) {
        if (!d.has(skill)) d.set(skill, []);
        d.get(skill).push(profit);
    }
    for (const arr of d.values()) {
        arr.sort((a, b) => a - b);
    }

    let ans = 0;
    for (const w of workers) {
        if (d.has(w) && d.get(w).length > 0) {
            ans += d.get(w).pop();
        }
    }

    let maxRem = 0;
    for (const arr of d.values()) {
        if (arr.length > 0) {
            maxRem = Math.max(maxRem, arr[arr.length - 1]);
        }
    }
    return ans + maxRem;
};
